/**
 * 查找所有散列函数的位置
 * 返回查找终止的位置，若找不到则返回 -1.
 */
int findPos( const AnyType & x ) const
{
    for( int i = 0; i < numHashFunctions; ++i )
    {
        int pos = myhash( x, i );

        if( isActive( pos ) && array[ pos ].element == x )
